-- Spatial details reviewed against the local French quest file and the cited
-- archived quest pages. These records contain locations, not puzzle solutions.
-- They are loaded before GeographyOnly.lua builds its objective/phase index.
local B=IHR_Runtime.Beta
local function key(r) return tostring(r.quest)..':'..B.Normalize(r.objective or '') end
local function merge(rows,records)
 local replace,phases={},{}
 for _,r in ipairs(records) do
  if r.binding=='iq_goal_rule' then replace[key(r)]=true end
  if r.step then phases[key(r)..'|'..B.Normalize(r.step)]=true end
 end
 for i=#rows,1,-1 do
  local r=rows[i]
  if replace[key(r)] and not r.step or r.step and phases[key(r)..'|'..B.Normalize(r.step)] then table.remove(rows,i) end
 end
 for _,r in ipairs(records) do rows[#rows+1]=r end
end
local fr='ImmersiveQuests/lang/fr.lua : '
local fear='Client FR et ImmersiveQuests FR, quête 4573 ; UESP Frighten the Fearsome, révision 3653367 : https://en.uesp.net/wiki/Online:Frighten_the_Fearsome'
local flower='ImmersiveQuests FR, quête 5080 ; UESP The Flower of Youth, révision 2916432 : https://en.uesp.net/wiki/Online:The_Flower_of_Youth'
local aldmeri={}
local function add(quest,objectives,text,target,kind,site,source,question)
 for _,objective in ipairs(objectives) do
  aldmeri[#aldmeri+1]={quest=quest,objective=objective,text=text,target=target,targetKind=kind,
   site=site,source=source or fr..'quête '..quest,binding='iq_goal_rule',answerComplete=true,question=question}
 end
end
local function phase(quest,objectives,steps,text,target,kind,site)
 for _,objective in ipairs(objectives) do for _,step in ipairs(steps) do
  aldmeri[#aldmeri+1]={quest=quest,objective=objective,step=step,text=text,target=target,targetKind=kind,
   site=site,source=fr..'quête '..quest,binding='iq_exact_phase',answerComplete=true}
 end end
end

